#!/usr/bin/env bash
# Round 377 claims (L29 + L56). Run from the loop root: bash b-round-376/claims-377.sh
# STORE=<tree> runs on another tree. K2 on the scratch reads the loop repo status (scratch is not a git tree); compare K2 only on store/. Sketch output (claims-377-sketch-output.txt) = STORE=b-round-376/scratch (A's round-376 tree + sketch-v3-delta.patch.txt).
S=${STORE:-/home/runner/czaba-project/store}
B=b-round-376
L=/home/runner/czaba-project/tmp/studio-real-loop
T=$S/app/lib/arrangement/__tests__
D=$S/docs/implementation/2026/quarter-IV
echo "K1 gate375: $(python3 -I -c "import json;d=json.load(open('gates/gate-round-375.json'));print(d['status'],d['commit'][:7])") gate376: $(python3 -I -c "import json;d=json.load(open('gates/gate-round-376.json'));print(d['status'],'-',d['reason'])")"
echo "K2 status-lines: $(git -C $S status --short --untracked-files=all 2>/dev/null | grep -v node_modules | wc -l)"
echo "K3 TC10 timeout: describe opens l.$(grep -n '^describe($' $T/transport-centre-ui.test.tsx | cut -d: -f1 | tr '\n' ' ')timeout line '$(grep -n 'timeout: 15_000,' $T/transport-centre-ui.test.tsx | tr -s ' ')' TC10 at l.$(grep -n "it('TC10 " $T/transport-centre-ui.test.tsx | cut -d: -f1) describe closes l.$(grep -n '^);$' $T/transport-centre-ui.test.tsx | cut -d: -f1 | tr '\n' ' ')file lines $(wc -l < $T/transport-centre-ui.test.tsx)"
echo "K4 TC10 times (ms): gate375 $(sed 's/\x1b\[[0-9;]*m//g' gates/round-375/verify.log | grep 'TC10 Play and Stop' | grep -oE '[0-9]+ms') B-v3-covering $(sed 's/\x1b\[[0-9;]*m//g' $B/covering-sketch-v3.log | grep 'TC10 Play and Stop' | grep -oE '[0-9]+ms') C376-standalone $(sed 's/\x1b\[[0-9;]*m//g' c-round-376/tc10.log | grep 'TC10 Play and Stop' | grep -oE '[0-9]+ms' | tr '\n' ' ')"
echo "K5 transitions on the hand-off path (ArrangementTransport, StudioWorkspace, ArrangementContext): $(cat $S/app/components/arrangement/ArrangementTransport.tsx $S/app/components/arrangement/StudioWorkspace.tsx $S/app/contexts/ArrangementContext.tsx | grep -cE 'startTransition|useTransition|useDeferredValue')"
echo "K6 row ids: RB-LEAF4 $(grep -c "'RB-LEAF4 " $T/render-budget.test.tsx) RB-LEAF4b $(grep -c "'RB-LEAF4b " $T/render-budget.test.tsx) FL11 $(grep -c "'FL11: " $T/self-disabling-focus.test.tsx)"
echo "K7 MASTER_MUTE_LABEL: $(grep -c "^const MASTER_MUTE_LABEL = 'Master Mute';$" $S/app/contexts/ArrangementContext.tsx) toggleMasterMute applyEdit uses it: $(grep -c 'MASTER_MUTE_LABEL);$' $S/app/contexts/ArrangementContext.tsx) undo+redo shared deps lines: $(grep -c '^  }, \[flushPendingClipGain, flushPendingMaster, flushPendingVolume, restoreHistory, setStatus\]);$' $S/app/contexts/ArrangementContext.tsx)"
echo "K8 protected: $(cd $S && sha256sum -c --quiet $L/b-round-318/protected-sha256.txt 2>&1 | wc -l) failing lines"
echo "K9 frozen (round-376 manifest, grants unchanged): $(cd $S && sha256sum -c --quiet $L/b-round-375/r376-frozen-sha256.txt 2>&1 | wc -l) failing lines, entries $(wc -l < b-round-375/r376-frozen-sha256.txt)"
echo "K10 v3 sketch files: $(cd $S && sha256sum -c --quiet $L/$B/sketch-v3-files-sha256.txt 2>/dev/null | wc -l) failing lines (0 = the 6 files equal v3); round-375 sketch: $(cd $S && sha256sum -c --quiet $L/b-round-375/sketch-files-sha256.txt 2>/dev/null | wc -l) failing lines (0 = v2, 1 = only render-budget differs)"
echo "K11 doc 243: files $(ls $D | grep -c '^243-') l.4 '$(sed -n 4p $D/243-perf-transport-leaves.md 2>/dev/null)' mentions RB-LEAF4b $(grep -c 'RB-LEAF4b' $D/243-perf-transport-leaves.md 2>/dev/null) MU-T-UNDO-FRESH-PER-EDIT $(grep -c 'MU-T-UNDO-FRESH-PER-EDIT' $D/243-perf-transport-leaves.md 2>/dev/null)"
echo "K12 expect/it counts: $(for f in render-budget drag-preview-render selection-wrappers-render self-disabling-focus; do p=$T/$f.test.tsx; printf '%s expect=%s it=%s; ' $f $(grep -c 'expect(' $p) $(grep -cE '^\s*it\(' $p); done)"
echo "K13 delta patch sha: $(sha256sum $B/sketch-v3-delta.patch.txt | cut -c1-16) dispatched: $(cut -c1-16 $B/sketch-v3-dispatched.sha256)"
echo "K14 B v3 runs: covering $(sed 's/\x1b\[[0-9;]*m//g' $B/covering-sketch-v3.log | grep -E '^ +(Test Files|Tests) ' | tr -s ' ' | tr '\n' ';') shuffle $(sed 's/\x1b\[[0-9;]*m//g' $B/shuffle-sketch.log | tr -s ' ' | tr '\n' ';') typecheck $(tail -1 $B/sketch-typecheck.log) biome '$(tail -1 $B/sketch-biome.log)'"
echo "K15 M1 mutant on sketch: $(sed 's/\x1b\[[0-9;]*m//g' $B/mutants/sketch-run/mutant-MU-T-UNDO-FRESH-PER-EDIT.full.log | grep -E '×' | sed 's/ [0-9]*ms$//' | tr -s ' ' | tr '\n' ';') $(sed 's/\x1b\[[0-9;]*m//g' $B/mutants/sketch-run/mutant-MU-T-UNDO-FRESH-PER-EDIT.full.log | grep -oE 'Tests +[0-9]+ failed')"
echo "K16 regression-last: $(python3 -I -c "import json;print(json.load(open('regression-last.json'))['date'])") lessons lines: $(wc -l < lessons.md) tasks/round-376.md sha: $(sha256sum tasks/round-376.md | cut -c1-16) current-task.md(376) archived equal: $(cmp -s tasks/round-376.md b-round-376/current-task-376.md && echo yes || echo no)"
echo "K17 covering files: $(wc -l < b-round-375/covering-376.txt)"
for f in $B/sketch-v3-delta.patch.txt $B/sketch-v3-dispatched.sha256 $B/sketch-v3-files-sha256.txt $B/grants-377.txt $B/covering-sketch-v3.log $B/shuffle-sketch.log $B/sketch-typecheck.log $B/sketch-biome.log $B/expect-counts-377.txt $B/mutants/run-mutant-377.sh $B/mutants/sketch-run/mutant-MU-T-UNDO-FRESH-PER-EDIT.full.log $B/rbleaf4b-sketch.log b-round-375/mutants/run-all-376.sh b-round-375/mutants/summary.txt b-round-375/probe/leaf-probe-376.mjs b-round-375/probe/leaf-sketch-376.json b-round-375/probe/recipe-probe-376.mjs b-round-375/perf-sketch-vs-head-json-all.txt b-round-375/perf-sketch.log b-round-375/r376-frozen-sha256.txt b-round-318/protected-sha256.txt c-round-376/tc10.log c-round-376/leaf-A.json c-round-376/recipe-A.json a-round-376.md c-round-376.json tasks/round-376.md; do echo "K18 exists $f: $(test -f $f && echo yes || echo MISSING)"; done
